										'@babel/preset-env',
										{
											loose: true,
											modules: false,
											targets: {
												browsers: ['last 2 versions', 'IE >= 11']
											}
										}
									]
							  ]
							: [],
						plugins: [
							coverage && [
								'istanbul',
								{
									include: minify ? '**/dist/**/*.js' : '**/src/**/*.js'
								}
							]
						].filter(Boolean)
					});
